export function PositionRelative({
  top = {{top}},
  left = {{left}},
  background = "{{background}}",
}) {
  const ghost = { position: "relative", width: 60, height: 60, border: "1.5px dashed #24143055", borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, color: "#24143066" };
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 320 }}
      role="img" aria-label="A relatively positioned box shifted from its original spot, which stays reserved in the layout as a dashed outline">
      <div style={{ display: "flex", gap: 10, background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 14, boxSizing: "border-box" }}>
        <div style={ghost}>1</div>
        <div style={ghost}>
          <span style={{ position: "absolute", top: -18, left: 0, fontSize: 9, color: "#24143088", whiteSpace: "nowrap" }}>original spot</span>
          <div style={{ position: "relative", width: 60, height: 60, borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center",
            fontWeight: 700, color: "#241430", boxShadow: "0 4px 10px rgba(36,20,48,.25)", background, top, left }}>2</div>
        </div>
        <div style={ghost}>3</div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>
        position: relative; top: {top}px; left: {left}px &mdash; box 2 moves, its space in the flow does not
      </p>
    </div>
  );
}
